import { styled, View } from '@tamagui/web';
import type { CSSProperties } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { customProperties } from '../../helpers/customProperties';
import { prependClassName } from '../../helpers/prependClassName';
import { size as toSize } from '../../styleTokens';
import type { DivAttributes } from '../../types/ElementAttributes';

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const throbberFrame = {
	render: 'div',
	display: 'flex',
	flexDirection: 'row',
	flexShrink: 1,
	alignItems: 'normal',
	justifyContent: 'center',
	minWidth: 'auto',
	minHeight: 'auto',
	marginBlock: '-1px',
} as const;

const throbberCircle = {
	render: 'span',
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	marginInline: '1px',
	width: 'var(--rcx-throbber-size, 1rem)',
	height: 'var(--rcx-throbber-size, 1rem)',
	borderRadius: '100%',
} as const;

const throbberTones = {
	primary: {
		backgroundColor: 'var(--rcx-color-button-background-primary-default, #156ff5)',
	},
	muted: {
		backgroundColor: 'var(--rcx-color-button-background-secondary-default, #e4e7ea)',
	},
	inherit: {
		backgroundColor: 'currentColor',
	},
} as const;

// end of generated

const ThrobberFrame = styled(View, { ...throbberFrame });

const CircleFrame = styled(View, {
	...throbberCircle,
	variants: {
		tone: throbberTones,
	},
});

type CircleProps = {
	circleCount: number;
	iteration: number;
	inheritColor?: boolean;
	disabled?: boolean;
	size: CSSProperties['blockSize'];
};

function Circle({ disabled, circleCount, iteration, inheritColor, size }: CircleProps) {
	const modifiers = `${disabled ? 'rcx-throbber__circle--disabled ' : ''}${inheritColor ? 'rcx-throbber__circle--inherit-color ' : ''}`;

	return (
		<CircleFrame
			tone={(inheritColor && 'inherit') || (disabled && 'muted') || 'primary'}
			className={`rcx-box rcx-box--full ${modifiers}rcx-throbber__circle`}
			render={
				<span
					{...customProperties({
						'--rcx-throbber-size': toSize(size),
						'--rcx-throbber-duration': `${circleCount * 0.466}s`,
						'--rcx-throbber-delay': `${iteration * 0.16}s`,
					})}
				/>
			}
		/>
	);
}

export type ThrobberProps = DivAttributes & {
	size?: CSSProperties['blockSize'];
	circleCount?: number;
	disabled?: boolean;
	inheritColor?: boolean;
};

/**
 * Indicates content that has not loaded yet.
 */
function Throbber(props: ThrobberProps) {
	const { disabled, size = 'x16', circleCount = 3, inheritColor, className } = props;

	return (
		<ThrobberFrame
			className={prependClassName(className, 'rcx-box rcx-box--full rcx-throbber')}
			render={<div {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} />}
		>
			{Array.from({ length: circleCount || 3 }, (_, iteration) => (
				<Circle
					key={iteration}
					circleCount={circleCount}
					iteration={iteration}
					disabled={!!disabled}
					size={size}
					inheritColor={!!inheritColor}
				/>
			))}
		</ThrobberFrame>
	);
}

export default Throbber;
